namespace Amib.Threading{}
class Program{static void Main(){string line;var job=typeof(PollServiceRequestManager).GetMethod("PoolWorkerJob",BindingFlags.Instance|BindingFlags.NonPublic);var running=typeof(PollServiceRequestManager).GetField("m_running",BindingFlags.Instance|BindingFlags.NonPublic);while((line=Console.ReadLine())!=null){var a=line.Split('|');Capture.Trace="";Capture.Fail=a[6];Host.Can=a[0]=="1";Host.Sending=a[1]=="1";Host.Has=a[2]=="1";Host.Started=int.Parse(a[3]);Host.Now=int.Parse(a[4]);Host.Pending=int.Parse(a[8]);Host.Watch=null;Host.Watching=false;var args=new PollServiceEventArgs(null,null,(r,id)=>{Capture.Event("has");return Host.Has;},(r,id)=>Data("get"),(r,id)=>Data("no"),(r,id)=>Capture.Event("drop"),OpenMetaverse.UUID.Zero,int.Parse(a[5]));if(a[10]=="nullhas")args.HasEvents=null;if(a[10]=="nullget")args.GetEvents=null;if(a[10]=="nullno")args.NoEvents=null;if(a[10]=="nulldrop")args.Drop=null;var req=new PollServiceHttpRequest(args,new OSHttpServer.Incoming());var manager=new PollServiceRequestManager(false,uint.Parse(a[7]),123);Host.Manager=manager;bool error=false;foreach(var op in a[9].Split(',')){try{switch(op){case "start":manager.Start();break;case "stop":manager.Stop();break;case "enqueue":manager.Enqueue(req);break;case "job":job.Invoke(manager,new object[]{req});break;case "null":job.Invoke(manager,new object[]{null});break;case "watch":Host.Watching=true;Host.WatchSleeps=0;Host.Watch();break;}}catch{error=true;Capture.Event("caught");}}Console.WriteLine(Capture.Trace+"handled:"+args.RequestsHandled+";running:"+((bool)running.GetValue(manager)?1:0)+";exception:"+(error?1:0));}}static Hashtable Data(string name){Capture.Event(name);return new Hashtable{{"h",new OSHttpResponse(null)}};}}
